-- =============================================================================
-- 003_CREATE_AND_SEED_ALUMNI.SQL
-- =============================================================================

CREATE TABLE IF NOT EXISTS aur_alumni (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  branch_id UUID REFERENCES aur_branches(id) ON DELETE SET NULL,
  course_id UUID REFERENCES aur_courses(id) ON DELETE SET NULL,
  cohort_name TEXT,
  graduation_year INTEGER NOT NULL,
  graduation_month TEXT NOT NULL,
  certification_name TEXT NOT NULL,
  certificate_serial_no TEXT UNIQUE NOT NULL,
  current_employer TEXT NOT NULL,
  job_title TEXT NOT NULL,
  employment_status TEXT NOT NULL DEFAULT 'Employed',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE aur_alumni ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "aur_alumni_all_access" ON aur_alumni;
CREATE POLICY "aur_alumni_all_access" ON aur_alumni FOR ALL USING (true) WITH CHECK (true);

ON CONFLICT (id) DO NOTHING;
